// Renders Readout's Plasma QML (popups and panel styles) to PNG files without showing a window.
// A development tool: it loads the real widget code and talks to the running readoutd.
//
//   plasma-preview --scene Popups.qml --output popups.png [--delay 4000]
#include <KLocalizedQmlContext>
#include <KLocalizedString>

#include <QCommandLineParser>
#include <QGuiApplication>
#include <QImage>
#include <QQmlApplicationEngine>
#include <QQmlContext>
#include <QQuickWindow>
#include <QTimer>

#include <cstdio>

// Generated by qt_add_qml_module for the applet's QML module (plasma.applet.io.github.aakash1122.readout).
void qml_register_types_plasma_applet_io_github_aakash1122_readout();

int main(int argc, char *argv[])
{
    if (qEnvironmentVariableIsEmpty("QT_QPA_PLATFORM")) {
        qputenv("QT_QPA_PLATFORM", "offscreen");
    }
    QGuiApplication app(argc, argv);

    QCommandLineParser parser;
    parser.addHelpOption();
    const QCommandLineOption sceneOption(QStringLiteral("scene"), QStringLiteral("QML scene file."), QStringLiteral("file"));
    const QCommandLineOption outputOption(QStringLiteral("output"), QStringLiteral("PNG file to write."), QStringLiteral("file"));
    const QCommandLineOption delayOption(QStringLiteral("delay"), QStringLiteral("Milliseconds to wait for data."), QStringLiteral("ms"),
                                         QStringLiteral("4000"));
    parser.addOptions({sceneOption, outputOption, delayOption});
    parser.process(app);
    if (!parser.isSet(sceneOption) || !parser.isSet(outputOption)) {
        parser.showHelp(1);
    }

    KLocalizedString::setApplicationDomain("plasma_applet_io.github.aakash1122.readout");
    qml_register_types_plasma_applet_io_github_aakash1122_readout();

    QQmlApplicationEngine engine;
    KLocalization::setupLocalizedContext(&engine);
    engine.load(QUrl::fromLocalFile(parser.value(sceneOption)));
    auto *window = engine.rootObjects().isEmpty() ? nullptr : qobject_cast<QQuickWindow *>(engine.rootObjects().constFirst());
    if (window == nullptr) {
        std::fprintf(stderr, "scene did not create a Window\n");
        return 1;
    }

    const QString output = parser.value(outputOption);
    QTimer::singleShot(parser.value(delayOption).toInt(), &app, [&app, window, output] {
        const QImage image = window->grabWindow();
        if (image.isNull() || !image.save(output)) {
            std::fprintf(stderr, "could not grab or save the window\n");
            app.exit(1);
            return;
        }
        app.quit();
    });
    return app.exec();
}
